def find_episode_lists(obj):
    found = []
    if isinstance(obj, list):
        if obj and all(isinstance(x, dict) and {"suite", "id", "seed"} <= set(x) for x in obj):
            found.append(obj)
        else:
            for x in obj:
                found.extend(find_episode_lists(x))
    elif isinstance(obj, dict):
        for x in obj.values():
            found.extend(find_episode_lists(x))
    return found

